// Expand around each of the 2n - 1 centres. O(n^2) time, O(1) space.
function longestPalindrome(s) {
  let bestL = 0, bestLen = 0;
  const expand = (l, r) => {
    while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; }
    // the palindrome is s[l+1 .. r-1]
    if (r - l - 1 > bestLen) { bestLen = r - l - 1; bestL = l + 1; }
  };
  for (let i = 0; i < s.length; i++) {
    expand(i, i);       // odd length, centre on a character
    expand(i, i + 1);   // even length, centre on a gap
  }
  return s.slice(bestL, bestL + bestLen);
}

function countSubstrings(s) {
  let count = 0;
  for (let c = 0; c < 2 * s.length - 1; c++) {
    let l = c >> 1, r = l + (c & 1);
    while (l >= 0 && r < s.length && s[l] === s[r]) { count++; l--; r++; }
  }
  return count;
}

// LeetCode 680 Valid Palindrome II: delete at most one character.
function validPalindrome(s) {
  const isPal = (l, r) => { while (l < r) if (s[l++] !== s[r--]) return false; return true; };
  let l = 0, r = s.length - 1;
  while (l < r) {
    if (s[l] !== s[r]) return isPal(l + 1, r) || isPal(l, r - 1);
    l++; r--;
  }
  return true;
}

def longest_palindrome(s):
    best = (0, 0)                        # (start, length)
    for i in range(len(s)):
        for l, r in ((i, i), (i, i + 1)):
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1
                r += 1
            if r - l - 1 > best[1]:
                best = (l + 1, r - l - 1)
    return s[best[0]:best[0] + best[1]]

def count_substrings(s):
    n, count = len(s), 0
    for c in range(2 * n - 1):
        l, r = c // 2, c // 2 + c % 2
        while l >= 0 and r < n and s[l] == s[r]:
            count += 1
            l -= 1
            r += 1
    return count

static String longestPalindrome(String s) {
    int bestL = 0, bestLen = 0;
    for (int i = 0; i < s.length(); i++) {
        for (int k = 0; k < 2; k++) {               // k = 0 odd, k = 1 even
            int l = i, r = i + k;
            while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { l--; r++; }
            if (r - l - 1 > bestLen) { bestLen = r - l - 1; bestL = l + 1; }
        }
    }
    return s.substring(bestL, bestL + bestLen);
}

int countSubstrings(const string& s) {
    int n = s.size(), count = 0;
    for (int c = 0; c < 2 * n - 1; c++) {
        int l = c / 2, r = l + c % 2;
        while (l >= 0 && r < n && s[l] == s[r]) { count++; l--; r++; }
    }
    return count;
}

// Prefix function: pi[i] = longest proper prefix of p[0..i] that is also a suffix.
function prefixFunction(p) {
  const pi = new Array(p.length).fill(0);
  for (let i = 1, k = 0; i < p.length; i++) {
    while (k > 0 && p[i] !== p[k]) k = pi[k - 1];   // fall back to a shorter border
    if (p[i] === p[k]) k++;
    pi[i] = k;
  }
  return pi;
}

// All start indices of pattern in text. O(n + m).
function kmpSearch(text, pattern) {
  if (pattern.length === 0) return [0];
  const pi = prefixFunction(pattern), res = [];
  for (let i = 0, k = 0; i < text.length; i++) {
    while (k > 0 && text[i] !== pattern[k]) k = pi[k - 1];
    if (text[i] === pattern[k]) k++;
    if (k === pattern.length) {
      res.push(i - k + 1);
      k = pi[k - 1];                                 // allow overlapping matches
    }
  }
  return res;
}

// LeetCode 28: first occurrence or -1
const strStr = (haystack, needle) => {
  const r = kmpSearch(haystack, needle);
  return r.length ? r[0] : -1;
};

// Z-function: z[i] = length of the longest common prefix of s and s[i..]
function zFunction(s) {
  const n = s.length, z = new Array(n).fill(0);
  for (let i = 1, l = 0, r = 0; i < n; i++) {
    if (i < r) z[i] = Math.min(r - i, z[i - l]);
    while (i + z[i] < n && s[z[i]] === s[i + z[i]]) z[i]++;
    if (i + z[i] > r) { l = i; r = i + z[i]; }
  }
  return z;
}

def prefix_function(p):
    pi = [0] * len(p)
    k = 0
    for i in range(1, len(p)):
        while k > 0 and p[i] != p[k]:
            k = pi[k - 1]
        if p[i] == p[k]:
            k += 1
        pi[i] = k
    return pi

def kmp_search(text, pattern):
    """All start indices, O(n + m)."""
    if not pattern:
        return [0]
    pi, res, k = prefix_function(pattern), [], 0
    for i, ch in enumerate(text):
        while k > 0 and ch != pattern[k]:
            k = pi[k - 1]
        if ch == pattern[k]:
            k += 1
        if k == len(pattern):
            res.append(i - k + 1)
            k = pi[k - 1]
    return res

def smallest_period(s):
    """Length of the shortest block that repeats to form s (s itself if none)."""
    p = len(s) - prefix_function(s)[-1]
    return p if len(s) % p == 0 else len(s)

static int[] prefixFunction(String p) {
    int[] pi = new int[p.length()];
    for (int i = 1, k = 0; i < p.length(); i++) {
        while (k > 0 && p.charAt(i) != p.charAt(k)) k = pi[k - 1];
        if (p.charAt(i) == p.charAt(k)) k++;
        pi[i] = k;
    }
    return pi;
}

// LeetCode 28 Find the Index of the First Occurrence in a String. O(n + m).
static int strStr(String text, String pat) {
    if (pat.isEmpty()) return 0;
    int[] pi = prefixFunction(pat);
    for (int i = 0, k = 0; i < text.length(); i++) {
        while (k > 0 && text.charAt(i) != pat.charAt(k)) k = pi[k - 1];
        if (text.charAt(i) == pat.charAt(k)) k++;
        if (k == pat.length()) return i - k + 1;
    }
    return -1;
}

vector<int> prefixFunction(const string& p) {
    vector<int> pi(p.size(), 0);
    for (int i = 1, k = 0; i < (int)p.size(); i++) {
        while (k > 0 && p[i] != p[k]) k = pi[k - 1];
        if (p[i] == p[k]) k++;
        pi[i] = k;
    }
    return pi;
}

// Rotate String: goal is a rotation of s iff it occurs in s + s.
bool rotateString(const string& s, const string& goal) {
    if (s.size() != goal.size()) return false;
    string t = goal + '#' + s + s;
    vector<int> pi = prefixFunction(t);
    for (int v : pi) if (v == (int)goal.size()) return true;
    return false;
}

// Rabin-Karp with verification. M < 2^31 and B < 2^21 keep products exact in doubles.
function rabinKarp(text, pattern) {
  const n = text.length, m = pattern.length, M = 2147483647, B = 131;
  if (m === 0) return 0;
  if (m > n) return -1;
  let high = 1;                                    // B^(m-1) mod M
  for (let i = 0; i < m - 1; i++) high = (high * B) % M;
  let hp = 0, ht = 0;
  for (let i = 0; i < m; i++) {
    hp = (hp * B + pattern.charCodeAt(i)) % M;
    ht = (ht * B + text.charCodeAt(i)) % M;
  }
  for (let i = 0; ; i++) {
    if (hp === ht && text.startsWith(pattern, i)) return i;  // verify on hash match
    if (i + m >= n) return -1;
    ht = (ht - ((text.charCodeAt(i) * high) % M) + M) % M;   // drop leading char
    ht = (ht * B + text.charCodeAt(i + m)) % M;              // shift and add new char
  }
}

// LeetCode 187 Repeated DNA Sequences: exact 20-bit rolling code, no collisions.
function findRepeatedDnaSequences(s) {
  const bits = { A: 0, C: 1, G: 2, T: 3 }, mask = (1 << 20) - 1;
  const seen = new Set(), added = new Set(), res = [];
  let code = 0;
  for (let i = 0; i < s.length; i++) {
    code = ((code << 2) | bits[s[i]]) & mask;
    if (i < 9) continue;
    if (seen.has(code) && !added.has(code)) { added.add(code); res.push(s.slice(i - 9, i + 1)); }
    seen.add(code);
  }
  return res;
}

import random

class SubstringHasher:
    """Prefix hashes: O(n) build, O(1) hash of any s[l:r]. Random base defeats anti-hash tests."""
    M = (1 << 61) - 1                     # Python ints never overflow

    def __init__(self, s):
        self.B = random.randrange(256, self.M - 1)
        n = len(s)
        self.h = [0] * (n + 1)
        self.pw = [1] * (n + 1)
        for i, ch in enumerate(s):
            self.h[i + 1] = (self.h[i] * self.B + ord(ch)) % self.M
            self.pw[i + 1] = (self.pw[i] * self.B) % self.M

    def get(self, l, r):
        return (self.h[r] - self.h[l] * self.pw[r - l]) % self.M

def has_all_codes(s, k):
    """LeetCode 1461: roll a k-bit integer, count distinct values."""
    need, mask, code, seen = 1 << k, (1 << k) - 1, 0, set()
    for i, ch in enumerate(s):
        code = ((code << 1) | (ch == "1")) & mask
        if i >= k - 1:
            seen.add(code)
            if len(seen) == need:
                return True
    return False

// Rabin-Karp with verification, long arithmetic. Expected O(n + m).
static int rabinKarp(String text, String pat) {
    final long M = 1_000_000_007L, B = 131;
    int n = text.length(), m = pat.length();
    if (m == 0) return 0;
    if (m > n) return -1;
    long high = 1, hp = 0, ht = 0;
    for (int i = 0; i < m - 1; i++) high = high * B % M;
    for (int i = 0; i < m; i++) {
        hp = (hp * B + pat.charAt(i)) % M;
        ht = (ht * B + text.charAt(i)) % M;
    }
    for (int i = 0; ; i++) {
        if (hp == ht && text.regionMatches(i, pat, 0, m)) return i;
        if (i + m >= n) return -1;
        ht = (ht - text.charAt(i) * high % M + M) % M;
        ht = (ht * B + text.charAt(i + m)) % M;
    }
}

// LeetCode 208 Implement Trie. Map-based children work for any alphabet.
class TrieNode {
  constructor() { this.children = new Map(); this.end = false; this.count = 0; }
}

class Trie {
  constructor() { this.root = new TrieNode(); }

  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch);
      node.count++;                       // words passing through this prefix
    }
    node.end = true;
  }

  #walk(s) {                              // never creates nodes
    let node = this.root;
    for (const ch of s) {
      node = node.children.get(ch);
      if (!node) return null;
    }
    return node;
  }

  search(word) { const n = this.#walk(word); return n !== null && n.end; }
  startsWith(prefix) { return this.#walk(prefix) !== null; }
  countPrefix(prefix) { const n = this.#walk(prefix); return n ? n.count : 0; }
}

// LeetCode 211: '.' matches any letter.
class WordDictionary extends Trie {
  addWord(w) { this.insert(w); }
  search(w) {
    const dfs = (node, i) => {
      if (i === w.length) return node.end;
      if (w[i] === '.') {
        for (const child of node.children.values()) if (dfs(child, i + 1)) return true;
        return false;
      }
      const next = node.children.get(w[i]);
      return next !== undefined && dfs(next, i + 1);
    };
    return dfs(this.root, 0);
  }
}

class TrieNode:
    __slots__ = ("children", "end")

    def __init__(self):
        self.children = {}
        self.end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.end = True

    def _walk(self, s):
        node = self.root
        for ch in s:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.end

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

def replace_words(dictionary, sentence):
    """LeetCode 648: replace each word with its shortest root."""
    trie = Trie()
    for root in dictionary:
        trie.insert(root)
    out = []
    for word in sentence.split():
        node, prefix = trie.root, word
        for i, ch in enumerate(word):
            node = node.children.get(ch)
            if node is None:
                break
            if node.end:
                prefix = word[:i + 1]
                break
        out.append(prefix)
    return " ".join(out)

// Array-based trie for lowercase a-z: fastest lookups, 26 slots per node.
class Trie {
    private static class Node {
        Node[] next = new Node[26];
        boolean end;
    }
    private final Node root = new Node();

    public void insert(String word) {
        Node node = root;
        for (char ch : word.toCharArray()) {
            int i = ch - 'a';
            if (node.next[i] == null) node.next[i] = new Node();
            node = node.next[i];
        }
        node.end = true;
    }

    private Node walk(String s) {
        Node node = root;
        for (char ch : s.toCharArray()) {
            node = node.next[ch - 'a'];
            if (node == null) return null;
        }
        return node;
    }

    public boolean search(String word) { Node n = walk(word); return n != null && n.end; }
    public boolean startsWith(String prefix) { return walk(prefix) != null; }
}

class Trie {
    struct Node {
        array<Node*, 26> next{};
        bool end = false;
    };
    Node* root = new Node();   // nodes are never freed; use a pool or unique_ptr outside interviews
public:
    void insert(const string& w) {
        Node* n = root;
        for (char c : w) {
            if (!n->next[c - 'a']) n->next[c - 'a'] = new Node();
            n = n->next[c - 'a'];
        }
        n->end = true;
    }
    bool search(const string& w) const {
        const Node* n = root;
        for (char c : w) { n = n->next[c - 'a']; if (!n) return false; }
        return n->end;
    }
    bool startsWith(const string& p) const {
        const Node* n = root;
        for (char c : p) { n = n->next[c - 'a']; if (!n) return false; }
        return true;
    }
};

// LeetCode 212 Word Search II with word-at-node and branch pruning.
function findWords(board, words) {
  const root = { kids: new Map(), word: null };
  for (const w of words) {
    let node = root;
    for (const ch of w) {
      if (!node.kids.has(ch)) node.kids.set(ch, { kids: new Map(), word: null });
      node = node.kids.get(ch);
    }
    node.word = w;
  }
  const R = board.length, C = board[0].length, found = [];

  function dfs(r, c, parent) {
    const ch = board[r][c];
    const node = parent.kids.get(ch);
    if (!node) return;
    if (node.word) { found.push(node.word); node.word = null; }
    board[r][c] = '#';
    if (r > 0) dfs(r - 1, c, node);
    if (r < R - 1) dfs(r + 1, c, node);
    if (c > 0) dfs(r, c - 1, node);
    if (c < C - 1) dfs(r, c + 1, node);
    board[r][c] = ch;
    if (node.kids.size === 0 && !node.word) parent.kids.delete(ch);  // prune
  }

  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) dfs(r, c, root);
  return found;
}

def find_words(board, words):
    """LeetCode 212 Word Search II: one grid DFS guided by a trie of all words."""
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = w                      # store the word at its end node

    rows, cols, found = len(board), len(board[0]), []

    def dfs(r, c, parent):
        ch = board[r][c]
        node = parent[ch]
        word = node.pop("$", None)         # report once, then forget it
        if word:
            found.append(word)
        board[r][c] = "#"                  # mark visited in place
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] in node:
                dfs(nr, nc, node)
        board[r][c] = ch                   # restore
        if not node:                       # prune exhausted branch
            parent.pop(ch)

    for r in range(rows):
        for c in range(cols):
            if board[r][c] in root:
                dfs(r, c, root)
    return found

static class Node { Node[] next = new Node[26]; String word; int children; }

static List<String> findWords(char[][] board, String[] words) {
    Node root = new Node();
    for (String w : words) {
        Node n = root;
        for (char ch : w.toCharArray()) {
            int i = ch - 'a';
            if (n.next[i] == null) { n.next[i] = new Node(); n.children++; }
            n = n.next[i];
        }
        n.word = w;
    }
    List<String> found = new ArrayList<>();
    for (int r = 0; r < board.length; r++)
        for (int c = 0; c < board[0].length; c++) dfs(board, r, c, root, found);
    return found;
}

static void dfs(char[][] b, int r, int c, Node parent, List<String> found) {
    if (r < 0 || c < 0 || r >= b.length || c >= b[0].length || b[r][c] == '#') return;
    char ch = b[r][c];
    Node node = parent.next[ch - 'a'];
    if (node == null) return;
    if (node.word != null) { found.add(node.word); node.word = null; }
    b[r][c] = '#';
    dfs(b, r + 1, c, node, found); dfs(b, r - 1, c, node, found);
    dfs(b, r, c + 1, node, found); dfs(b, r, c - 1, node, found);
    b[r][c] = ch;
    if (node.children == 0 && node.word == null) {   // prune
        parent.next[ch - 'a'] = null;
        parent.children--;
    }
}

// LeetCode 421 Maximum XOR of Two Numbers in an Array: binary trie.
function findMaximumXOR(nums) {
  const root = [null, null];
  for (const x of nums) {
    let node = root;
    for (let b = 30; b >= 0; b--) {
      const bit = (x >> b) & 1;
      if (!node[bit]) node[bit] = [null, null];
      node = node[bit];
    }
  }
  let best = 0;
  for (const x of nums) {
    let node = root, cur = 0;
    for (let b = 30; b >= 0; b--) {
      const bit = (x >> b) & 1;
      if (node[1 - bit]) { cur |= 1 << b; node = node[1 - bit]; }  // opposite bit wins
      else node = node[bit];
    }
    best = Math.max(best, cur);
  }
  return best;
}

// LeetCode 1268 with a sorted array and binary search (no trie).
function suggestedProducts(products, searchWord) {
  products.sort();
  const lowerBound = (target) => {
    let lo = 0, hi = products.length;
    while (lo < hi) { const mid = (lo + hi) >> 1; products[mid] < target ? (lo = mid + 1) : (hi = mid); }
    return lo;
  };
  const res = [];
  let prefix = '';
  for (const ch of searchWord) {
    prefix += ch;
    const start = lowerBound(prefix), row = [];
    for (let i = start; i < Math.min(start + 3, products.length); i++)
      if (products[i].startsWith(prefix)) row.push(products[i]);
    res.push(row);
  }
  return res;
}

def suggested_products(products, search_word):
    """LeetCode 1268 with a trie that keeps the 3 smallest words per node."""
    root = {}
    for p in sorted(products):
        node = root
        for ch in p:
            node = node.setdefault(ch, {"#": []})
            if len(node["#"]) < 3:
                node["#"].append(p)
    out, node = [], root
    for ch in search_word:
        node = node.get(ch) if node else None
        out.append(node["#"] if node else [])
    return out

def find_maximum_xor(nums):
    """LeetCode 421: binary trie, greedily pick the opposite bit. O(n * 31)."""
    root, best = {}, 0
    for x in nums:
        node = root
        for b in range(30, -1, -1):
            node = node.setdefault((x >> b) & 1, {})
    for x in nums:
        node, cur = root, 0
        for b in range(30, -1, -1):
            bit = (x >> b) & 1
            if 1 - bit in node:
                cur |= 1 << b
                node = node[1 - bit]
            else:
                node = node[bit]
        best = max(best, cur)
    return best

// LeetCode 1268 Search Suggestions System: trie with up to 3 sorted words per node.
static class Node { Node[] next = new Node[26]; List<String> top = new ArrayList<>(3); }

static List<List<String>> suggestedProducts(String[] products, String searchWord) {
    Arrays.sort(products);
    Node root = new Node();
    for (String p : products) {
        Node n = root;
        for (char ch : p.toCharArray()) {
            if (n.next[ch - 'a'] == null) n.next[ch - 'a'] = new Node();
            n = n.next[ch - 'a'];
            if (n.top.size() < 3) n.top.add(p);     // sorted insertion order = 3 smallest
        }
    }
    List<List<String>> res = new ArrayList<>();
    Node n = root;
    for (char ch : searchWord.toCharArray()) {
        n = (n == null) ? null : n.next[ch - 'a'];
        res.add(n == null ? new ArrayList<>() : n.top);
    }
    return res;
}

// LeetCode 136 Single Number: pairs cancel under XOR.
const singleNumber = (nums) => nums.reduce((acc, x) => acc ^ x, 0);

// LeetCode 191 Number of 1 Bits (Kernighan): one iteration per set bit.
function hammingWeight(n) {
  n = n >>> 0;                    // treat as unsigned 32-bit
  let count = 0;
  while (n !== 0) { n = (n & (n - 1)) >>> 0; count++; }
  return count;
}

// LeetCode 338 Counting Bits: bits[i] = bits[i >> 1] + (i & 1).
function countBits(n) {
  const bits = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) bits[i] = bits[i >> 1] + (i & 1);
  return bits;
}

// LeetCode 190 Reverse Bits (32-bit unsigned).
function reverseBits(n) {
  let res = 0;
  for (let i = 0; i < 32; i++) {
    res = (res << 1) | (n & 1);
    n >>>= 1;
  }
  return res >>> 0;               // without this, results >= 2^31 come out negative
}

// LeetCode 260 Single Number III: split by a bit where the two answers differ.
function singleNumberIII(nums) {
  const xor = nums.reduce((a, x) => a ^ x, 0);
  const low = xor & -xor;         // lowest set bit
  let a = 0, b = 0;
  for (const x of nums) (x & low) ? (a ^= x) : (b ^= x);
  return [a, b];
}

def single_number_ii(nums):
    """LeetCode 137: every number appears 3 times except one. Count bits mod 3."""
    res = 0
    for b in range(32):
        count = sum((x >> b) & 1 for x in nums) % 3
        if count:
            res |= 1 << b
    return res - (1 << 32) if res >= 1 << 31 else res   # back to signed 32-bit

def get_sum(a, b):
    """LeetCode 371: add without + using 32-bit masking (Python ints are unbounded)."""
    MASK, MAX = 0xFFFFFFFF, 0x7FFFFFFF
    while b & MASK:
        a, b = (a ^ b) & MASK, ((a & b) << 1) & MASK
    return a if a <= MAX else ~(a ^ MASK)

def missing_number(nums):
    """LeetCode 268: XOR indices 0..n with values; the missing one survives."""
    res = len(nums)
    for i, x in enumerate(nums):
        res ^= i ^ x
    return res

// LeetCode 191: Java has a built-in; the loop shows the idea.
static int hammingWeight(int n) {
    int count = 0;
    while (n != 0) { n &= n - 1; count++; }   // works for negative n too: 32 iterations max
    return count;                             // same as Integer.bitCount(n)
}

// LeetCode 371 Sum of Two Integers.
static int getSum(int a, int b) {
    while (b != 0) {
        int carry = (a & b) << 1;
        a ^= b;
        b = carry;
    }
    return a;
}

// LeetCode 231 Power of Two.
static boolean isPowerOfTwo(int n) { return n > 0 && (n & (n - 1)) == 0; }

// LeetCode 190 Reverse Bits with unsigned arithmetic (no undefined behaviour).
uint32_t reverseBits(uint32_t n) {
    uint32_t res = 0;
    for (int i = 0; i < 32; i++) {
        res = (res << 1) | (n & 1u);
        n >>= 1;
    }
    return res;
}

// LeetCode 338 Counting Bits via "clear lowest set bit".
vector<int> countBits(int n) {
    vector<int> bits(n + 1, 0);
    for (int i = 1; i <= n; i++) bits[i] = bits[i & (i - 1)] + 1;
    return bits;
}

// Subsets via masks (n <= 20 or so).
function subsets(nums) {
  const n = nums.length, res = [];
  for (let mask = 0; mask < (1 << n); mask++) {
    const s = [];
    for (let i = 0; i < n; i++) if ((mask >> i) & 1) s.push(nums[i]);
    res.push(s);
  }
  return res;
}

// LeetCode 847 Shortest Path Visiting All Nodes: BFS over (node, visitedMask).
function shortestPathLength(graph) {
  const n = graph.length, full = (1 << n) - 1;
  const seen = Array.from({ length: n }, () => new Uint8Array(1 << n));
  let frontier = [];
  for (let v = 0; v < n; v++) { frontier.push([v, 1 << v]); seen[v][1 << v] = 1; }
  for (let steps = 0; frontier.length; steps++) {
    const next = [];
    for (const [v, mask] of frontier) {
      if (mask === full) return steps;
      for (const u of graph[v]) {
        const m = mask | (1 << u);
        if (!seen[u][m]) { seen[u][m] = 1; next.push([u, m]); }
      }
    }
    frontier = next;
  }
  return 0;
}

def subsets(nums):
    """LeetCode 78 with masks: O(n * 2^n)."""
    n = len(nums)
    return [[nums[i] for i in range(n) if mask >> i & 1] for mask in range(1 << n)]

def submasks(mask):
    """Every subset of `mask`, largest first, ending with 0."""
    sub = mask
    while sub:
        yield sub
        sub = (sub - 1) & mask
    yield 0

def tsp(dist):
    """Held-Karp: cheapest tour starting and ending at city 0. O(2^n * n^2)."""
    n = len(dist)
    INF = float("inf")
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0                                 # visited {0}, standing at 0
    for mask in range(1 << n):
        for v in range(n):
            cur = dp[mask][v]
            if cur == INF:
                continue
            for u in range(n):
                if not mask >> u & 1:
                    nxt = mask | 1 << u
                    if cur + dist[v][u] < dp[nxt][u]:
                        dp[nxt][u] = cur + dist[v][u]
    full = (1 << n) - 1
    return min(dp[full][v] + dist[v][0] for v in range(n))

def max_length(arr):
    """LeetCode 1239: concatenate strings with all-unique letters, via 26-bit masks."""
    masks = []
    for s in arr:
        m = 0
        for ch in s:
            bit = 1 << (ord(ch) - 97)
            if m & bit:                          # repeated letter inside s
                m = -1
                break
            m |= bit
        if m != -1:
            masks.append(m)
    best = 0
    def dfs(i, used):
        nonlocal best
        best = max(best, bin(used).count("1"))
        for j in range(i, len(masks)):
            if not used & masks[j]:
                dfs(j + 1, used | masks[j])
    dfs(0, 0)
    return best

// LeetCode 201 Bitwise AND of Numbers Range: keep the common binary prefix.
static int rangeBitwiseAnd(int left, int right) {
    int shift = 0;
    while (left != right) { left >>= 1; right >>= 1; shift++; }
    return left << shift;
}

// Iterate all submasks of every mask: O(3^n) total.
static long countSubmaskPairs(int n) {
    long pairs = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        for (int sub = mask; sub > 0; sub = (sub - 1) & mask) pairs++;
        pairs++;                                   // the empty submask
    }
    return pairs;                                  // equals 3^n
}
